import React, { useMemo, useState } from "react"

import Shell from "../components/layout/Shell"
import Panel from "../components/layout/Panel"
import Breadcrumb from "../components/ui/Breadcrumb"
import { Delta, MetricCard, TickerMark } from "../components/ui"

import { getAllNews } from "../data/news"
import { getWatchlist } from "../data/markets"
import { describeSource } from "../data/source"

/**
 * News.
 *
 * Every headline the ingest pulled, filterable by symbol and source, with each
 * item carrying the move its subject made that session.
 *
 * WHY THE PRICE MOVE SITS ON EVERY HEADLINE. A news feed with no prices is a
 * reading list — you cannot tell which of forty stories mattered. Pairing each
 * headline with its symbol's change is what turns it into something you scan:
 * the story on a name that moved 8% is worth opening, the one on a name that
 * moved 0.2% usually is not.
 *
 * WHAT THE PAIRING IS NOT. It is not a claim of causation. The change shown is
 * the session move for that symbol, not an effect attributed to that article —
 * several stories on one name all carry the same figure, which is the honest
 * presentation of "here is what the stock did, here is what was written".
 */

const DASH = "—"
const isNum = v => typeof v === "number" && Number.isFinite(v)

/** "3 hours ago" — the form people actually want from a timestamp. */
function ago(unixSeconds) {
  if (!isNum(unixSeconds)) return null
  const ms = Date.now() - unixSeconds * 1000
  if (ms < 0) return "just now"
  const mins = Math.floor(ms / 60000)
  if (mins < 60) return `${Math.max(1, mins)} min ago`
  const hours = Math.floor(mins / 60)
  if (hours < 24) return `${hours} hour${hours === 1 ? "" : "s"} ago`
  const days = Math.floor(hours / 24)
  if (days < 30) return `${days} day${days === 1 ? "" : "s"} ago`
  const months = Math.floor(days / 30)
  return `${months} month${months === 1 ? "" : "s"} ago`
}

function stamp(unixSeconds) {
  if (!isNum(unixSeconds)) return DASH
  return new Date(unixSeconds * 1000).toLocaleString(undefined, {
    year: "numeric", month: "short", day: "2-digit", hour: "2-digit", minute: "2-digit",
  })
}

export default function NewsPage({ location }) {
  const [symbol, setSymbol] = useState("all")
  const [source, setSource] = useState("all")

  const all = useMemo(() => getAllNews() || [], [])
  const watchlist = useMemo(() => getWatchlist(), [])
  const provenance = useMemo(() => describeSource(), [])

  /** Session change per symbol, so each headline can carry its subject's move. */
  const changeFor = useMemo(() => {
    const map = new Map()
    for (const row of watchlist) map.set(row.symbol, row.changePct)
    return map
  }, [watchlist])

  const symbols = useMemo(
    () => [...new Set(all.map(n => n.symbol).filter(Boolean))].sort(),
    [all]
  )
  const sources = useMemo(
    () => [...new Set(all.map(n => n.source).filter(Boolean))].sort(),
    [all]
  )

  const items = useMemo(() => {
    let out = all
    if (symbol !== "all") out = out.filter(n => n.symbol === symbol)
    if (source !== "all") out = out.filter(n => n.source === source)
    return [...out].sort((a, b) => (b.timestamp ?? 0) - (a.timestamp ?? 0))
  }, [all, symbol, source])

  const newest = items[0]?.timestamp
  const covered = new Set(all.map(n => n.symbol)).size

  return (
    <Shell location={location}>
      <div className="page">
        <header className="page__head">
          <div className="page__heading">
            <Breadcrumb items={[{ label: "MarketScan", to: "/" }, { label: "News" }]} />
            <h1 className="page__title">News</h1>
            <p className="page__lede">
              Headlines across the universe, each paired with what its subject did that session.
            </p>
          </div>
          <div className="page__aside">
            <span className="news__source">{provenance.label}</span>
          </div>
        </header>

        <section className="section">
          <div className="markets__metrics">
            <MetricCard label="Stories" value={all.length} meta="in the current ingest" />
            <MetricCard label="Symbols covered" value={covered} meta={`of ${watchlist.length} tracked`} />
            <MetricCard
              label="Most recent"
              value={newest ? (ago(newest) || DASH) : DASH}
              meta={newest ? stamp(newest) : "nothing ingested yet"}
            />
            <MetricCard label="Publishers" value={sources.length} meta="distinct sources" />
          </div>
        </section>

        <section className="section">
          <div className="section__head">
            <div className="section__heading">
              <h2 className="section__title">
                {items.length === all.length
                  ? "All headlines"
                  : `${items.length} of ${all.length} headlines`}
              </h2>
            </div>

            <div className="news__filters">
              <label className="news__filter">
                <span className="news__filter-label">Symbol</span>
                <select
                  className="news__select"
                  value={symbol}
                  onChange={e => setSymbol(e.target.value)}
                >
                  <option value="all">All symbols</option>
                  {symbols.map(s => (
                    <option key={s} value={s}>{s}</option>
                  ))}
                </select>
              </label>

              <label className="news__filter">
                <span className="news__filter-label">Source</span>
                <select
                  className="news__select"
                  value={source}
                  onChange={e => setSource(e.target.value)}
                >
                  <option value="all">All sources</option>
                  {sources.map(s => (
                    <option key={s} value={s}>{s}</option>
                  ))}
                </select>
              </label>
            </div>
          </div>

          <Panel flush>
            {items.length === 0 ? (
              <p className="news__empty">
                No stories match this filter. The ingest pulls a handful of recent headlines
                per symbol, so narrow combinations can legitimately be empty.
              </p>
            ) : (
              <ul className="news__list">
                {items.map(item => {
                  const change = changeFor.get(item.symbol)
                  return (
                    <li className="news__item" key={item.id}>
                      <div className="news__mark">
                        <TickerMark symbol={item.symbol} size={30} />
                      </div>

                      <div className="news__body">
                        <div className="news__meta">
                          <span className="news__symbol">{item.symbol}</span>
                          {isNum(change) && (
                            <Delta value={change} percent digits={2} />
                          )}
                          <span className="news__dot">·</span>
                          <span className="news__publisher">{item.source}</span>
                          <span className="news__dot">·</span>
                          <span className="news__time" title={stamp(item.timestamp)}>
                            {ago(item.timestamp) || DASH}
                          </span>
                        </div>

                        <h3 className="news__headline">
                          {item.url ? (
                            <a
                              className="news__link"
                              href={item.url}
                              target="_blank"
                              rel="noreferrer noopener"
                            >
                              {item.headline}
                            </a>
                          ) : (
                            item.headline
                          )}
                        </h3>

                        {item.summary && <p className="news__summary">{item.summary}</p>}
                      </div>
                    </li>
                  )
                })}
              </ul>
            )}
          </Panel>

          <p className="news__note">
            The change beside each headline is that symbol&rsquo;s move for the session — not a
            claim that the story caused it. Several stories on one name will show the same
            figure.
          </p>
        </section>
      </div>
    </Shell>
  )
}

export const Head = () => <title>News · MarketScan</title>
